import { escapeRegExp } from '@unocss/core'

type InlineStyles = boolean | ((id?: string) => boolean) | undefined

/**
 * Extend Nuxt's `features.inlineStyles` so the CSS generated by UnoCSS is always inlined.
 * Everything else is left to the original value.
 */
export function withInlineUnoCss(inlineStyles: InlineStyles, virtualModulePrefix = '__uno') {
  const unoCssRe = new RegExp(`[/\\\\]${escapeRegExp(virtualModulePrefix)}(?:_.*?)?\\.css(?:\\?.*)?$`)
  return (id?: string) => {
    if (id && unoCssRe.test(id))
      return true
    return typeof inlineStyles === 'function' ? inlineStyles(id) : inlineStyles !== false
  }
}
